-- 45_deal_titles_pass2.sql — titles for the deals 44 couldn't match
-- =====================================================================
-- For deals still without a title, finds their row in the Excel by:
--   A) the deal's contact e-mail = "Email de contacto" (or the company e-mail
--      = "Cliente: Email"), created the same day ±1;
--   B) a similar company name (trigram similarity ≥ 0.35), same day ±1;
--   C) the only untitled deal and the only unused Excel row on that exact day.
-- Each Excel row is used once. Never overwrites an existing title.
--   1. Run as it is: PREVIEW (changes nothing). 2. Change 'no' to 'yes' to apply.
-- Undo: update public.trackings t set deal_name = b.old_name
--       from public.deals_bk44_titles b where b.id = t.id and b.pass = 2;
-- =====================================================================

