declare
  apply text := 'no';   -- >>> FILL THE TITLES <<<  change 'no' to 'yes' after checking the preview
  v_tenant text := '11f85bbc-8ef6-442a-bc53-915949f9f013';
  has_trgm boolean;
begin
  perform set_config('search_path', 'public, extensions', true);
  select exists (select 1 from pg_proc where proname = 'similarity') into has_trgm;

  drop table if exists pg_temp._x45, pg_temp._e45, pg_temp._t45, pg_temp._m45;
  create temp table _x45 (cliente text, titulo text, d date, email text, cemail text);
