('Zumex Group, SA','Zumex Group SA','2020-12-21',NULL,'zumex@zumex.com'),
('Zummo','Zummo','2025-09-01','jlledo@zummo.es',NULL),
('Zummo','Zummo','2020-03-25','amunoz@zummo.es',NULL),
('Zumosol','Zumosol','2022-02-10',NULL,'info@zumospalma.com'),
('Zunder','Zunder','2025-10-23','julia.gonzalez@zunder.com',NULL);

  -- Excel rows not already used by 44 (a deal of that company/day already has that title)
  create temp table _e45 as
  select row_number() over () as eid, x.*, regexp_replace(lower(translate(coalesce(x.cliente,''), 'áàäâãéèëêíìïîóòöôõúùüûñçÁÀÄÂÃÉÈËÊÍÌÏÎÓÒÖÔÕÚÙÜÛÑÇ', 'aaaaaeeeeiiiiooooouuuuncaaaaaeeeeiiiiooooouuuunc')), '[^a-z0-9 ]', '', 'g') as cn
  from _x45 x
  where not exists (
    select 1 from public.trackings t join public.companies c on c.id = t.company_id
    where (to_jsonb(t) ->> 'tenant_id') = v_tenant
      and t.deal_name = x.titulo
      and abs(((to_jsonb(t) ->> 'created_at')::timestamptz at time zone 'UTC')::date - x.d) <= 1);

  create temp table _t45 as
  select t.id, ((to_jsonb(t) ->> 'created_at')::timestamptz at time zone 'UTC')::date as d,
         regexp_replace(lower(translate(coalesce(c.name,''), 'áàäâãéèëêíìïîóòöôõúùüûñçÁÀÄÂÃÉÈËÊÍÌÏÎÓÒÖÔÕÚÙÜÛÑÇ', 'aaaaaeeeeiiiiooooouuuuncaaaaaeeeeiiiiooooouuuunc')), '[^a-z0-9 ]', '', 'g') as cn,
         lower(nullif(trim(to_jsonb(c) ->> 'email'), '')) as cemail,
         (select array_agg(distinct lower(trim(ct.email))) from public.tracking_contacts tc
            join public.contacts ct on ct.id = tc.contact_id
           where tc.tracking_id = t.id and coalesce(trim(ct.email), '') <> '') as emails
  from public.trackings t left join public.companies c on c.id = t.company_id
  where (to_jsonb(t) ->> 'tenant_id') = v_tenant and coalesce(trim(t.deal_name), '') = '';

  create temp table _m45 (id uuid primary key, eid bigint unique, titulo text, how text);

  -- A) e-mail + day ±1
  insert into _m45
  select distinct on (a.id) a.id, a.eid, a.titulo, 'email'
  from (
    select t.id, e.eid, e.titulo, abs(t.d - e.d) dd,
           row_number() over (partition by e.eid order by abs(t.d - e.d), t.id) re
    from _t45 t join _e45 e
      on abs(t.d - e.d) <= 1
     and ((e.email is not null and e.email = any(t.emails)) or (e.cemail is not null and e.cemail = t.cemail))
  ) a where a.re = 1
  order by a.id, a.dd, a.eid
  on conflict do nothing;

  -- B) similar company name + day ±1
  if has_trgm then
    insert into _m45
    select distinct on (a.id) a.id, a.eid, a.titulo, 'similar name'
    from (
      select t.id, e.eid, e.titulo, similarity(t.cn, e.cn) s,
             row_number() over (partition by e.eid order by similarity(t.cn, e.cn) desc, t.id) re
      from _t45 t join _e45 e on abs(t.d - e.d) <= 1 and t.cn <> '' and e.cn <> '' and similarity(t.cn, e.cn) >= 0.35
      where not exists (select 1 from _m45 m where m.id = t.id)
        and not exists (select 1 from _m45 m where m.eid = e.eid)
    ) a where a.re = 1
    order by a.id, a.s desc, a.eid
    on conflict do nothing;
  end if;

  -- C) the only one left on both sides on that exact day
  insert into _m45
  select t.id, e.eid, e.titulo, 'only one that day'
  from (select * from _t45 t where not exists (select 1 from _m45 m where m.id = t.id)) t
  join (select * from _e45 e where not exists (select 1 from _m45 m where m.eid = e.eid)) e on e.d = t.d
  where (select count(*) from _t45 t2 where t2.d = t.d and not exists (select 1 from _m45 m where m.id = t2.id)) = 1
    and (select count(*) from _e45 e2 where e2.d = t.d and not exists (select 1 from _m45 m where m.eid = e2.eid)) = 1
  on conflict do nothing;

  if apply is distinct from 'yes' then
    raise notice 'Preview only. Change ''no'' to ''yes'' on the line marked FILL THE TITLES to apply.';
    return;
  end if;

  if to_regclass('public.deals_bk44_titles') is null then
    create table public.deals_bk44_titles (id uuid primary key, old_name text, new_name text, at timestamptz default now());
    alter table public.deals_bk44_titles enable row level security;
  end if;
  alter table public.deals_bk44_titles add column if not exists pass int default 1;
  insert into public.deals_bk44_titles (id, old_name, new_name, pass)
  select t.id, t.deal_name, m.titulo, 2 from public.trackings t join _m45 m on m.id = t.id
  on conflict (id) do nothing;

  update public.trackings t set deal_name = m.titulo
  from _m45 m where m.id = t.id and coalesce(trim(t.deal_name), '') = '';
end $$;

select 'SUMMARY' as what,
       (select count(*) from _t45)::text || ' deals without title · matched: ' ||
       (select count(*) from _m45 where how = 'email')::text || ' by e-mail, ' ||
       (select count(*) from _m45 where how = 'similar name')::text || ' by similar name, ' ||
       (select count(*) from _m45 where how = 'only one that day')::text || ' as the only one that day · left: ' ||
       ((select count(*) from _t45) - (select count(*) from _m45))::text as detail,
       null::text as company, null::date as created, null::text as title, null::text as how
union all
(select 'example', null, c.name, ((to_jsonb(t) ->> 'created_at')::timestamptz at time zone 'UTC')::date, m.titulo, m.how
 from _m45 m join public.trackings t on t.id = m.id left join public.companies c on c.id = t.company_id
 order by m.how, c.name limit 30);
